const payload = $json.body || $json;
const message = (payload.message || payload.text || payload.body || payload.query || payload.input || payload.content || '').toString().trim();

const normalize = (value) => (value || '').toString().trim().toLowerCase();
const fromPayloadLang = normalize(payload.language || payload.lang || payload.locale || payload.preferred_language || payload.user_language);
const fromSessionLang = normalize(payload.session_state && payload.session_state.language ? payload.session_state.language : payload.session_language);
const rawHeaderLang = payload.headers?.['accept-language'] || payload.headers?.acceptLanguage || payload.headers?.accept_language || '';
const fromHeaderLang = normalize(typeof rawHeaderLang === 'string' ? rawHeaderLang.split(',')[0].split('-')[0] : rawHeaderLang);
const defaultLang = normalize(
  payload.default_language ||
  payload.defaultLanguage ||
  payload.config?.default_language ||
  payload.config?.language ||
  'es'
);

const detectLanguageFromMessage = (text) => {
  const content = String(text || '');
  if (!content) return '';

  const accentCount = (content.normalize('NFD').replace(/[^\p{L}]/gu, '').match(/[áéíóúüñ¿¡]/gi) || []).length;
  const tokenized = content
    .toLowerCase()
    .replace(/[^a-záéíóúüñ¿¡0-9\s]+/gi, ' ')
    .split(/\s+/)
    .filter(Boolean);
  const tokenSet = new Set(tokenized);

  const spanishWords = ['hola', 'gracias', 'cómo', 'como', 'quiero', 'necesito', 'puedo', 'quieres', 'ayuda', 'servicios', 'credito', 'crédito', 'impuesto', 'impuestos', 'empresa', 'negocio', 'cita', 'citas', 'agendar', 'consulta'];
  const englishWords = ['hello', 'hi', 'thanks', 'thank', 'help', 'you', 'can', 'need', 'want', 'service', 'services', 'what', 'how', 'please', 'when', 'where', 'consultation', 'schedule', 'appointment', 'tax', 'credit', 'loan'];

  const countMatches = (keywords) => keywords.reduce((total, word) => tokenSet.has(word) ? total + 1 : total, 0);
  const spanishScore = countMatches(spanishWords) + Math.min(accentCount, 2);
  const englishScore = countMatches(englishWords);

  if (spanishScore > englishScore) return 'es';
  if (englishScore > spanishScore) return 'en';
  if (accentCount > 0) return 'es';

  return '';
};

const detectedLang = detectLanguageFromMessage(message);
const resolvedLang = (detectedLang === 'en' || detectedLang === 'es') ? detectedLang : ((fromPayloadLang === 'en' || fromPayloadLang === 'es') ? fromPayloadLang : ((fromSessionLang === 'en' || fromSessionLang === 'es') ? fromSessionLang : ((fromHeaderLang === 'en' || fromHeaderLang === 'es') ? fromHeaderLang : ((defaultLang === 'en' || defaultLang === 'es') ? defaultLang : 'es'))));

const sessionId = (payload.session_id || payload.sessionId || payload.customer_id || '').toString();
const finalSessionId = sessionId || ('sgs_' + Date.now());

return [{
  json: {
    workflow_execution_id: $execution.id,
    session_id: finalSessionId,
    customer_id: (payload.customer_id || '').toString(),
    channel: (payload.channel || 'web').toString(),
    message,
    language: resolvedLang,
    conversation_stage: payload.conversation_stage || '',
    collected_fields: payload.collected_fields || {},
    recent_context: Array.isArray(payload.recent_context) ? payload.recent_context : [],
    session_state: payload.session_state || {},
    previous_intent: payload.previous_intent || '',
    session_update_hint: payload.session_update_hint || {},
    language_detected: detectedLang || '',
    language_source: fromPayloadLang ? 'payload' : (detectedLang ? 'message' : (fromSessionLang ? 'session' : (fromHeaderLang ? 'header' : 'default'))),
    orchestration_payload: {
      session_id: finalSessionId,
      customer_id: payload.customer_id || '',
      channel: payload.channel || 'web',
      message,
      language: resolvedLang,
      language_source: fromPayloadLang ? 'payload' : (detectedLang ? 'message' : (fromSessionLang ? 'session' : (fromHeaderLang ? 'header' : 'default'))),
      language_detected: detectedLang || '',
      session_state: payload.session_state || {},
      collected_fields: payload.collected_fields || {},
      recent_messages: Array.isArray(payload.recent_messages) ? payload.recent_messages : [],
      default_language: defaultLang
    },
    sessionApiEnabled: !!(payload.sessionApiEnabled || payload.sessionApi || payload.session_api_enabled),
    loggerEnabled: !!(payload.loggerEnabled || payload.logEnabled || payload.logger_enabled)
  }
}];

const payload = $json.orchestration_payload || $json || {};
const preferredLanguage = (payload.language || payload.lang || payload.locale || payload.preferred_language || payload.user_language || '').toString().toLowerCase();
const resolvedLang = (preferredLanguage === 'en' || preferredLanguage === 'es') ? preferredLanguage : 'es';
return [{
  json: {
    workflow_execution_id: payload.workflow_execution_id || $execution.id,
    session_id: payload.session_id || '',
    customer_id: payload.customer_id || '',
    channel: payload.channel || 'web',
    message: (payload.message || '').toString().trim(),
    language: resolvedLang,
    conversation_stage: payload.conversation_stage || '',
    current_service: payload.current_service || payload.service || 'general',
    pending_action: payload.pending_action || '',
    collected_fields: payload.collected_fields || {},
    recent_messages: Array.isArray(payload.recent_messages) ? payload.recent_messages : [],
    session_state: payload.session_state || {},
    sessionApiEnabled: !!(payload.sessionApiEnabled || payload.sessionApi || payload.session_api_enabled),
    loggerEnabled: !!(payload.loggerEnabled || payload.logEnabled || payload.logger_enabled),
    default_language: payload.default_language || resolvedLang
  }
}];

const rawInput = $json || {};
const responseCandidate = rawInput?.body || rawInput?.data || rawInput?.payload || rawInput?.response || rawInput?.result || rawInput;

const hasOrchestratorShape = (obj) => obj && typeof obj === 'object' && (obj.intent || obj.response || obj.reply || obj.session_id || obj.tool || obj.message || obj.final_message || obj.output);

let response = responseCandidate;
let result = null;

if (hasOrchestratorShape(response)) {
  result = response;
} else if (typeof response === 'string' || response instanceof String) {
  const text = response.toString().trim();
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      if (hasOrchestratorShape(parsed)) {
        result = parsed;
        response = parsed;
      }
    } catch (err) {}
  }
} else if (response && typeof response === 'object' && hasOrchestratorShape(response?.payload)) {
  result = response.payload;
  response = response.payload;
} else if (response && typeof response === 'object') {
  const nested = response.body || response.data || response.result;
  if (hasOrchestratorShape(nested)) {
    result = nested;
    response = nested;
  }
}

if (!result) {
  // Try to extract JSON from common LLM response shapes
  const candidateText =
    (response?.choices?.[0]?.message?.content) ||
    response?.content ||
    response?.message ||
    response?.text ||
    response?.reply ||
    response?.final_message ||
    response?.output ||
    '';

  let parsed = null;
  if (typeof candidateText === 'string' && candidateText.trim()) {
    try {
      const match = candidateText.match(/\{[\s\S]*\}/);
      parsed = match ? JSON.parse(match[0]) : null;
    } catch (err) {
      parsed = null;
    }
  }

  if (parsed && hasOrchestratorShape(parsed)) {
    result = parsed;
    response = parsed;
  }
}

const langSource = (result?.language || response?.language || rawInput?.language || 'es').toString().toLowerCase();
const inputLanguage = ($node['Normalize Incoming Message'].json.language || $node['Prepare Orchestrator Payload'].json.language || 'es').toString().toLowerCase();
const lang = (langSource === 'en' || langSource === 'es') ? langSource : (inputLanguage === 'en' ? 'en' : 'es');

const responseText =
  (result?.response ||
   result?.reply ||
   result?.final_message ||
   result?.output ||
   response?.response ||
   response?.reply ||
   response?.message ||
   response?.final_message ||
   response?.output ||
   responseTextFallback(rawInput) ||
   '').toString();

function responseTextFallback(input) {
  const candidateText =
    (input?.body && (input.body.response || input.body.reply || input.body.message || input.body.final_message || input.body.output)) ||
    (input?.data && (input.data.response || input.data.reply || input.data.message || input.data.final_message || input.data.output)) ||
    '';
  return candidateText?.toString() || '';
}

const hasError = Boolean(result?.error || rawInput?.error || response === null || response === undefined);
const parsedResponseText = responseText.trim();
const success = !hasError && hasOrchestratorShape(result) && (parsedResponseText.length > 0 || (typeof result.response === 'string' && result.response.trim().length > 0));
const fallbackText = lang === 'en'
  ? 'I could not process the request right now. Please try again in a few seconds.'
  : 'No pude procesar la solicitud en este momento. Intenta en unos segundos.';

const finalResponseText = (parsedResponseText.length > 0)
  ? parsedResponseText
  : ((result?.response && result.response.toString().trim().length > 0) ? result.response.toString().trim() : fallbackText);

const finalIntent = result?.intent || (hasError ? 'UNCLEAR' : 'UNCLEAR');
const finalTool = result?.tool || 'NONE';
const finalSession = result?.session_id || rawInput?.session_id || rawInput?.sessionId || '';
const finalCustomer = result?.customer_id || rawInput?.customer_id || '';
const finalChannel = result?.channel || rawInput?.channel || 'web';

return [{
  json: {
    workflow_execution_id: result?.workflow_execution_id || rawInput?.workflow_execution_id || $execution.id,
    session_id: finalSession.toString(),
    customer_id: finalCustomer.toString(),
    channel: finalChannel.toString(),
    language: lang,
    intent: finalIntent,
    tool: finalTool,
    handoff_required: result?.handoff_required === true,
    response: finalResponseText || fallbackText,
    session_update: result?.session_update || {
      conversation_stage: success ? 'orchestrated' : 'error',
      current_intent: finalIntent || 'UNCLEAR',
      current_service: result?.service || result?.current_service || 'general',
      pending_action: finalTool || 'NONE',
      collected_fields: result?.collected_fields || {}
    },
    log_payload: result?.log_payload || {
      event_type: 'MESSAGE_RECEIVED',
      intent: finalIntent || 'UNCLEAR',
      selected_tool: finalTool || 'NONE',
      duration: Number(result?.duration || 0),
      success: success,
      error_type: hasError ? 'orchestrator_error' : ''
    },
    orchestration_raw: result || response,
    success: success
  }
}];

const lang = $json.language === 'en' ? 'en' : 'es';
const responseText = ($json.response || '').toString().trim();
const replyText = responseText.length > 0
  ? responseText
  : (lang === 'en'
      ? 'I could not generate a valid response from the assistant. Please retry.'
      : 'No pude generar una respuesta valida. Intenta nuevamente.');

return [{
  json: {
    session_id: $json.session_id || '',
    customer_id: $json.customer_id || '',
    channel: $json.channel || 'web',
    language: lang,
    reply: replyText,
    response: replyText,
    intent: 'UNCLEAR',
    tool: 'NONE',
    handoff_required: true,
    session_update: { current_intent: 'UNCLEAR', conversation_stage: 'error', pending_action: 'NONE', collected_fields: {}, last_messages: [] },
    log_payload: { event_type: 'TOOL_ERROR', intent: 'UNCLEAR', selected_tool: 'NONE', duration: 0, success: false, error_type: 'orchestrator_parse_failure' },
    workflow_execution_id: $json.workflow_execution_id || '',
    success: false
  }
}];

const input = $json || {};
const payload = input.body || input;
return [{
  json: {
    logged: true,
    session_id: input.session_id || payload.session_id || '',
    customer_id: input.customer_id || payload.customer_id || '',
    channel: input.channel || payload.channel || 'web',
    language: input.language || payload.language || 'es',
    intent: input.intent || payload.intent || 'UNCLEAR',
    tool: input.tool || payload.tool || 'NONE',
    duration: Number(input.duration || payload.duration || 0),
    success: input.success || payload.success || true,
    error_type: input.error_type || payload.error_type || '',
    reply: input.reply || payload.reply || '',
    workflow_execution_id: input.workflow_execution_id || payload.workflow_execution_id || ''
  }
}];
